  function printNow(){context();const w=window.open('','_blank');if(!w)throw Error('팝업 차단을 해제해주세요.');S.printWindows.push(w);w.document.write(`<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>초자내부교정일지</title><style>@page{size:A4 landscape;margin:12mm}*{box-sizing:border-box}body{font:10pt/1.45 "Malgun Gothic",sans-serif;color:#223a44;margin:0}nav{padding:12px;position:sticky;top:0;background:#fff}button{padding:8px 18px}h1{text-align:center;font-size:19pt;margin:12px 0 20px}.print-top,.print-meta,.print-footer,.print-sign{display:flex;justify-content:space-between;gap:16px;font-size:9pt;margin:12px 0}.print-top{color:#607887}.print-table{width:100%;border-collapse:collapse;font-size:8pt}th,td{border:1px solid #9caab1;padding:6px 3px;text-align:center}th{background:#f1f5f5}.print-item,.print-note{text-align:left;overflow-wrap:anywhere}.print-note{max-width:35mm;white-space:normal}.actual-date-source{display:block;font-size:7pt;color:#687b83}small{font-size:7pt}.print-sign{justify-content:flex-end;gap:50px}.photo-sheet{break-before:page}.print-photo-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}figure{margin:0}figcaption{text-align:center;margin:12px}img,.print-photo-empty{width:100%;height:125mm;object-fit:contain;border:1px solid #adbcc4}.print-sheet{break-after:page}.print-sheet:last-child{break-after:auto}thead{display:table-header-group}tr{break-inside:avoid}@media print{nav{display:none}}</style></head><body><nav><button id="qiPrintButton">인쇄 / PDF 저장</button></nav>${$('printContent').innerHTML}</body></html>`);w.document.close();w.document.getElementById('qiPrintButton').onclick=()=>w.print();}
  function quantityItems(){const count=Number($('newQuantity').value),code=$('newCode').value.trim(),room=500-S.draft.items.length;if(!Number.isInteger(count)||count<1||count>room)throw Error(`추가 수량은 1~${Math.max(0,room)}개입니다.`);if(!code||code.length>60)throw Error('시작 관리번호를 입력해주세요.');const match=code.match(/^(.*?)(\d+)$/);if(count>1&&!match)throw Error('여러 개를 추가할 때는 관리번호 끝에 순번을 넣어주세요.');const codes=[];for(let i=0;i<count;i++){let next=code;if(count>1){const number=Number(match[2])+i;if(!Number.isSafeInteger(number))throw Error('관리번호 순번이 너무 큽니다.');next=match[1]+String(number).padStart(match[2].length,'0');}if(next.length>60||S.draft.items.some(x=>x.code.trim()===next))throw Error(`이미 등록되었거나 사용할 수 없는 관리번호: ${next}`);codes.push(next);}return codes;}
