  function openBatchCriteria(){context();if(!writable())return;const items=visible(),eligible=[],excluded=[],groups=new Map();let confirmed=0;for(const item of items){const answer=M().confirmCriteria(item);if(!answer.ok){excluded.push({code:item.code,reason:answer.errors.map(x=>x.message).join(' ')});continue;}if(item.criteriaConfirmed){confirmed++;continue;}eligible.push(item.id);const key=JSON.stringify([item.kind,capacityKey(item.nominal),item.material,item.beta,item.tolerance,item.mode]);if(!groups.has(key))groups.set(key,{item,count:0});groups.get(key).count++;}S.batch={token:stamp(),draft:S.draft,snapshot:JSON.stringify(S.draft),scopeIds:JSON.stringify(items.map(x=>x.id)),eligible};$('batchScope').textContent=batchScope()+' · 전체 페이지 '+items.length+'개';$('batchSummary').innerHTML=`<span>확인 가능 <b>${eligible.length}</b></span><span>이미 확인 <b>${confirmed}</b></span><span>제외 <b>${excluded.length}</b></span>`;$('batchGroups').innerHTML=groups.size?`<table><thead><tr><th>초자</th><th>재질</th><th>팽창계수</th><th>허용오차 (mL)</th><th>수량</th></tr></thead><tbody>${[...groups.values()].map(({item,count})=>`<tr><td>${esc(item.name)}<small>${esc(item.mode)}</small></td><td>${esc(item.material)}</td><td>${esc(item.beta)}</td><td>± ${esc(item.tolerance)}</td><td>${count}개</td></tr>`).join('')}</tbody></table>`:'<p class="batch-empty">새로 확인할 수 있는 항목이 없습니다.</p>';$('batchExcluded').innerHTML=excluded.length?`<details class="batch-excluded"><summary>기준 미입력·오류 ${excluded.length}개 제외</summary><ul>${excluded.slice(0,50).map(x=>`<li><strong>${esc(x.code)}</strong> ${esc(x.reason)}</li>`).join('')}</ul>${excluded.length>50?`<p>외 ${excluded.length-50}개</p>`:''}</details>`:'';$('batchStatus').textContent='';$('batchApply').textContent=eligible.length+'개 기준 확인';$('batchDialog').showModal();paintIcons($('batchDialog'));applyPermission();}
